import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledKpiDrillDownTable = styled.div({
  width: '100%',
  height: '100%',
  '.ag-header': {
    borderWidth: '0px 0px 1px 0px !important',
    borderStyle: 'solid !important',
    borderColor: `${theme.colors.border.light} !important`,
  },

  '.ag-header-cell': {
    fontWeight: '400',
    borderWidth: '0px 1px 0 1px',
    borderStyle: 'solid',
    borderColor: `${theme.colors.border.light}`,

    '&.ag-column-first': {
      borderLeft: 'none',
    },

    '&.ag-column-last': {
      borderRight: 'none',
    },
  },

  '.ag-cell': {
    border: `1px solid ${theme.colors.border.light}`,

    img: {
      width: '24px !important',
      height: '24px !important',
      border: `0.6px solid ${theme.colors.border.default}`,
      borderRadius: '50%',
    },

    '[data-main-flag]': {
      width: '24px !important',
      height: '24px !important',
      border: `0.6px solid ${theme.colors.border.default}`,
      borderRadius: '50%',
      backgroundColor: 'transparent',
    },

    '[data-flag-badge] img': {
      width: '100% !important',
      height: '100% !important',
      objectFit: 'cover',
    },

    '&.ag-column-first': {
      borderLeft: 'none',
    },

    '&.ag-column-last': {
      borderRight: 'none',
    },
  },

  '.ag-cell-refresh-status-actual > .ag-cell-content > div': {
    backgroundColor: `${theme.colors.specificProperty.successBackground} !important`,
    color: `${theme.colors.specificProperty.successText} !important`,
  },

  '.ag-cell-refresh-status-le > .ag-cell-content > div': {
    backgroundColor: `${theme.colors.specificProperty.warningBackground} !important`,
    color: `${theme.colors.specificProperty.warningText} !important`,
  },
});
